// Helper to generate session token
function generateSessionToken(): string {
  return generateUUID();
}

function base64UrlEncodeBytes(bytes: Uint8Array): string {
  const base64 =
    typeof Buffer !== "undefined"
      ? Buffer.from(bytes).toString("base64")
      : btoa(String.fromCharCode(...bytes));
  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function generateRandomBase64Url(byteLength: number): string {
  const bytes = new Uint8Array(byteLength);
  crypto.getRandomValues(bytes);
  return base64UrlEncodeBytes(bytes);
}

async function sha256Base64Url(input: string): Promise<string> {
  const encoded = new TextEncoder().encode(input);
  const digest = await crypto.subtle.digest("SHA-256", encoded);
  return base64UrlEncodeBytes(new Uint8Array(digest));
}

function setSessionCookie(c: any, name: string, value: string, maxAgeSeconds: number) {
  const cookieOptions = getSessionCookieOptions(c);
  setCookie(c, name, value, {
    ...cookieOptions,
    maxAge: maxAgeSeconds,
  });
}

function clearSessionCookie(c: any, name: string) {
  const cookieOptions = getSessionCookieOptions(c);
  setCookie(c, name, "", {
    ...cookieOptions,
    maxAge: 0,
  });
}

function isLocalDevelopmentHost(hostname: string): boolean {
  const normalized = hostname.trim().toLowerCase();
  return (
    normalized === "localhost" ||
    normalized === "127.0.0.1" ||
    normalized === "::1" ||
    normalized.endsWith(".localhost")
  );
}

function getSessionCookieOptions(c: any) {
  const requestUrl = (() => {
    try {
      return new URL(c.req.url);
    } catch {
      return null;
    }
  })();
  const originUrl = (() => {
    const origin = c.req.header("origin");
    if (typeof origin !== "string" || !origin.trim()) {
      return null;
    }

    try {
      return new URL(origin);
    } catch {
      return null;
    }
  })();

  const localHttpCandidates = [requestUrl, originUrl];
  for (const candidate of localHttpCandidates) {
    if (!candidate) {
      continue;
    }

    const localHttp =
      candidate.protocol === "http:" && isLocalDevelopmentHost(candidate.hostname);
    if (localHttp) {
      return {
        httpOnly: true,
        path: "/",
        sameSite: "lax" as const,
        secure: false,
      };
    }
  }

  const forwardedProto = String(c.req.header("x-forwarded-proto") || "")
    .split(",")[0]
    .trim()
    .toLowerCase();
  if (
    requestUrl?.protocol === "https:" ||
    originUrl?.protocol === "https:" ||
    forwardedProto === "https"
  ) {
    return {
      httpOnly: true,
      path: "/",
      sameSite: "none" as const,
      secure: true,
    };
  }

  return {
    httpOnly: true,
    path: "/",
    sameSite: "none" as const,
    secure: true,
  };
}

// Helper to normalize email
function normalizeEmail(email: string): string {
  return email.toLowerCase().trim();
}

function normalizeText(value: unknown): string {
  if (typeof value === "string") {
    return value.trim();
  }
  if (value === null || value === undefined) {
    return "";
  }
  return String(value).trim();
}

function isValidUserHandle(handle: string): boolean {
  return normalizeUserHandleInput(handle) !== null;
}

// Helper to validate email format
function isValidEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Helper to validate password
function isValidPassword(password: string): boolean {
  return password.length >= 8;
}

type VerifiedCentralIdentityGrant = {
  token: string;
  keyId: string | null;
  claims: CentralIdentityGrantClaims;
};

function normalizeOptionalLocale(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function normalizeResponseErrorMessage(data: any, fallback: string): string {
  if (typeof data === "string" && data.trim()) {
    return data.trim();
  }
  if (typeof data?.error === "string" && data.error.trim()) {
    return data.error.trim();
  }
  if (typeof data?.message === "string" && data.message.trim()) {
    return data.message.trim();
  }
  return fallback;
}

function normalizeRemoteHttpErrorMessage(response: Response, data: any, fallback: string): string {
  const statusSuffix = response?.status ? ` (HTTP ${response.status})` : "";
  return normalizeResponseErrorMessage(data, `${fallback}${statusSuffix}`);
}

function normalizeDbBoolean(value: unknown, fallback = false): boolean {
  if (typeof value === "boolean") {
    return value;
  }
  if (value !== null && value !== undefined && String(value).trim() !== "") {
    const numeric = Number(value);
    if (Number.isFinite(numeric)) {
      return numeric !== 0;
    }
  }
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase();
  if (!normalized) return fallback;
  if (["true", "t", "yes", "y", "on"].includes(normalized)) return true;
  if (["false", "f", "no", "n", "off"].includes(normalized)) return false;
  return fallback;
}

async function parseJsonResponseSafe(response: Response): Promise<any> {
  try {
    return await response.json();
  } catch {
    return null;
  }
}

async function callCentralIdentityEndpoint(
  env: Env,
  pathname: string,
  body: Record<string, unknown>
): Promise<{
  response: Response;
  data: any;
  verifiedGrant: VerifiedCentralIdentityGrant | null;
}> {
  const response = await fetch(buildCentralIdentityEndpointUrl(env, pathname), {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify(body),
  });
  const data = await parseJsonResponseSafe(response);
  const rawGrantToken =
    typeof data?.grant?.token === "string"
      ? data.grant.token
      : typeof data?.grant_token === "string"
      ? data.grant_token
      : "";

  let verifiedGrant: VerifiedCentralIdentityGrant | null = null;
  if (rawGrantToken) {
    const verified = await verifyCentralIdentityGrant(env, rawGrantToken);
    verifiedGrant = {
      token: rawGrantToken,
      keyId: verified.keyId,
      claims: verified.claims,
    };
  }

  return {
    response,
    data,
    verifiedGrant,
  };
}

async function callCentralIdentityAuthorizedEndpoint(
  env: Env,
  pathname: string,
  input: {
    method?: "DELETE" | "GET" | "PATCH" | "POST" | "PUT";
    token: string;
    body?: Record<string, unknown>;
  }
): Promise<{
  response: Response;
  data: any;
}> {
  const response = await fetch(buildCentralIdentityEndpointUrl(env, pathname), {
    method: input.method || "PATCH",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${input.token}`,
    },
    body: input.body ? JSON.stringify(input.body) : undefined,
  });
  const data = await parseJsonResponseSafe(response);
  return {
    response,
    data,
  };
}

