// Central identity endpoints
app.post("/api/identity/signup", async (c) => {
  await ensureRuntimeSchema(c.env);
  await ensureCentralIdentitySchema(c.env.DB);

  if (!isCentralIdentityServerConfigured(c.env)) {
    return c.json({ error: "Central identity server is not configured." }, 503);
  }

  try {
    const body = await c.req.json<{
      email: string;
      password: string;
      handle?: string;
      country_code?: string;
    }>();

    const email = normalizeEmail(body.email);
    const password = body.password;
    const countryCode = normalizeCountryCode(body.country_code, null);

    if (!isValidEmail(email)) {
      return c.json({ error: "Invalid email format" }, 400);
    }
    if (!isValidPassword(password)) {
      return c.json({ error: "Password must be at least 8 characters" }, 400);
    }

    const existing = await c.env.DB
      .prepare(`SELECT * FROM server_users WHERE LOWER(email) = LOWER(?) LIMIT 1`)
      .bind(email)
      .first();
    if (existing) {
      return c.json({ error: "Email already registered" }, 409);
    }

    const passwordHash = await bcrypt.hash(password, 10);
    const createdUser = await createServerUserRecord(c.env.DB, {
      email,
      passwordHash,
      preferredHandle: body.handle,
      countryCode,
    });
    if (!createdUser) {
      throw new Error("Failed to create central identity user.");
    }

    const response = await issueCentralIdentityGrantResponse(c.env, c.env.DB, createdUser, {
      countryCode,
    });
    return c.json(response, 201);
  } catch (error) {
    console.error("[IDENTITY] Signup failed:", error);
    return c.json({ error: "Central identity signup failed" }, 500);
  }
});

app.post("/api/identity/login", async (c) => {
  await ensureRuntimeSchema(c.env);
  await ensureCentralIdentitySchema(c.env.DB);

  if (!isCentralIdentityServerConfigured(c.env)) {
    return c.json({ error: "Central identity server is not configured." }, 503);
  }

  try {
    const body = await c.req.json<{
      email: string;
      password: string;
      handle?: string;
      country_code?: string;
    }>();

    const email = normalizeEmail(body.email);
    const password = body.password;
    const countryCode = normalizeCountryCode(body.country_code, null);

    if (!isValidEmail(email) || !password) {
      return c.json({ error: "Invalid email or password" }, 400);
    }

    const existing = await c.env.DB
      .prepare(`SELECT * FROM server_users WHERE LOWER(email) = LOWER(?) LIMIT 1`)
      .bind(email)
      .first();
    if (!existing) {
      return c.json({ error: "Invalid email or password" }, 401);
    }

    const passwordMatches = await bcrypt.compare(
      password,
      String((existing as any).password_hash || "")
    );
    if (!passwordMatches) {
      return c.json({ error: "Invalid email or password" }, 401);
    }

    const nowIso = new Date().toISOString();
    await updateServerUserLoginMetadata(c.env.DB, (existing as any).id, {
      countryCode,
      lastLoginAt: nowIso,
    });

    const refreshedUser = {
      ...(existing as any),
      last_login_at: nowIso,
      country_code: countryCode || (existing as any).country_code || null,
      updated_at: nowIso,
    };
    const response = await issueCentralIdentityGrantResponse(
      c.env,
      c.env.DB,
      refreshedUser,
      {
        ...(normalizeDbBoolean((existing as any).is_active, true)
          ? {}
          : {
              forceLogout: true,
              reason: "admin_disabled",
            }),
        countryCode,
      }
    );
    return c.json(response, 200);
  } catch (error) {
    console.error("[IDENTITY] Login failed:", error);
    return c.json({ error: "Central identity login failed" }, 500);
  }
});

