app.post("/api/identity/google-upsert", async (c) => {
  await ensureRuntimeSchema(c.env);
  await ensureCentralIdentitySchema(c.env.DB);

  let body:
    | {
        id_token?: string;
        country_code?: string;
        handle?: string;
      }
    | null = null;
  try {
    body = await c.req.json<{
      id_token?: string;
      country_code?: string;
      handle?: string;
    }>();
  } catch {
    body = null;
  }

  if (!body) {
    return c.json({ error: "Invalid request body" }, 400);
  }

  const idToken = typeof body.id_token === "string" ? body.id_token.trim() : "";
  if (!idToken) {
    return c.json({ error: "Google id_token is required." }, 400);
  }

  let googleUser: GoogleOAuthUser;
  try {
    googleUser = await buildGoogleUserFromIdToken(c.env, idToken);
  } catch (error) {
    console.error("[IDENTITY] Google upsert token verification failed:", error);
    const message =
      error instanceof Error ? error.message : String(error || "Invalid Google identity token.");
    if (message.includes("GOOGLE_OAUTH_CLIENT_ID")) {
      return c.json({ error: "Google identity sync is not configured on the server." }, 503);
    }
    return c.json({ error: "Invalid Google identity token." }, 401);
  }

  if (!isGoogleEmailVerified(googleUser)) {
    return c.json({ error: "Google account email is not verified." }, 403);
  }

  const email = getNormalizedGoogleEmail(googleUser);
  const googleSubject = getGoogleSubject(googleUser);
  const countryCode = normalizeCountryCode(body.country_code, null);
  const preferredHandle = normalizeUserHandleInput(body.handle);

  if (!isValidEmail(email)) {
    return c.json({ error: "Google account email is invalid." }, 400);
  }
  if (!googleSubject) {
    return c.json({ error: "Google account subject is missing." }, 400);
  }

  let existing = await c.env.DB
    .prepare(`SELECT * FROM server_users WHERE LOWER(email) = LOWER(?) LIMIT 1`)
    .bind(email)
    .first();

  const nowIso = new Date().toISOString();
  let statusCode = 200;

  if (!existing) {
    if (!countryCode) {
      return c.json({ error: "Country is required to create an account with Google." }, 400);
    }

    existing = await createServerUserRecord(c.env.DB, {
      email,
      passwordHash: `!google_oauth:${googleSubject}`,
      preferredHandle,
      countryCode,
    });
    statusCode = 201;
  } else {
    await updateServerUserLoginMetadata(c.env.DB, (existing as any).id, {
      countryCode,
      lastLoginAt: nowIso,
    });

    existing = await c.env.DB
      .prepare(`SELECT * FROM server_users WHERE id = ? LIMIT 1`)
      .bind((existing as any).id)
      .first();
  }

  if (!existing) {
    return c.json({ error: "Failed to create or load Google central identity." }, 500);
  }

  const resolvedServerUser = await ensureServerUserHandle(c.env.DB, existing, {
    preferredHandle,
  });
  const resolvedCountryCode = normalizeCountryCode(
    (resolvedServerUser as any).country_code,
    null
  );

  await ensureAppUserRow(c.env.DB, {
    id: String((resolvedServerUser as any).public_id || ""),
    email: String((resolvedServerUser as any).email || ""),
    auth_provider: "google",
    country_code: resolvedCountryCode,
    locale: null,
    handle: String((resolvedServerUser as any).handle || ""),
  });
  await updateAppUserHandle(
    c.env.DB,
    String((resolvedServerUser as any).public_id || ""),
    String((resolvedServerUser as any).handle || "")
  );

  return c.json(
    {
      success: true,
      user: {
        server_id: String((resolvedServerUser as any).id || ""),
        public_id: String((resolvedServerUser as any).public_id || ""),
        email: String((resolvedServerUser as any).email || ""),
        handle: normalizeUserHandleInput((resolvedServerUser as any).handle),
        country_code: resolvedCountryCode,
        is_active: normalizeDbBoolean((resolvedServerUser as any).is_active, true),
        auth_version: Number((resolvedServerUser as any).auth_version || 0),
        created_at: String((resolvedServerUser as any).created_at || ""),
        updated_at: String((resolvedServerUser as any).updated_at || ""),
      },
    },
    statusCode as any
  );
});

app.patch("/api/identity/handle", async (c) => {
  await ensureRuntimeSchema(c.env);
  await ensureCentralIdentitySchema(c.env.DB);

  if (!isCentralIdentityServerConfigured(c.env)) {
    return c.json({ error: "Central identity server is not configured." }, 503);
  }

  const authorizationHeader =
    c.req.header("authorization") || c.req.header("Authorization");
  if (!authorizationHeader || !authorizationHeader.startsWith("Bearer ")) {
    return c.json({ error: "Missing or invalid Authorization header" }, 401);
  }

  const grantToken = authorizationHeader.slice("Bearer ".length).trim();
  let verifiedGrant: Awaited<ReturnType<typeof verifyCentralIdentityGrant>> | null = null;
  try {
    verifiedGrant = await verifyCentralIdentityGrant(c.env, grantToken);
  } catch (error) {
    console.error("[IDENTITY] Handle update grant verification failed:", error);
    return c.json({ error: "Invalid or expired central identity grant." }, 401);
  }
  if (!verifiedGrant) {
    return c.json({ error: "Invalid or expired central identity grant." }, 401);
  }

  const body = await c.req
    .json<{
      handle?: string;
    }>()
    .catch(() => null);
  if (!body) {
    return c.json({ error: "Invalid request body" }, 400);
  }

  const normalizedHandle = normalizeUserHandleInput(body.handle);
  if (!normalizedHandle || !isValidUserHandle(normalizedHandle)) {
    return c.json({ error: "Handle cannot be empty or contain spaces" }, 400);
  }

  const publicId = verifiedGrant.claims.public_id;
  const serverUser = await getServerUserByPublicId(c.env.DB, publicId);
  if (!serverUser) {
    return c.json({ error: "Central identity user not found." }, 404);
  }

  const currentHandle = normalizeUserHandleInput((serverUser as any).handle);
  if (currentHandle !== normalizedHandle) {
    if (
      await serverUserHandleExists(c.env.DB, normalizedHandle, {
        excludePublicId: publicId,
      })
    ) {
      return c.json({ error: "Handle already in use." }, 409);
    }

    try {
      await c.env.DB
        .prepare(
          `UPDATE server_users
           SET handle = ?, updated_at = ?
           WHERE public_id = ?`
        )
        .bind(normalizedHandle, new Date().toISOString(), publicId)
        .run();
    } catch (error) {
      if (
        isDatabaseUniqueConstraintError(error, [
          "server_users.handle",
          "idx_server_users_handle_unique",
          "handle",
        ])
      ) {
        return c.json({ error: "Handle already in use." }, 409);
      }
      console.error("[IDENTITY] Handle update failed:", error);
      return c.json({ error: "Failed to update handle." }, 500);
    }
  }

  const refreshedUser = await getServerUserByPublicId(c.env.DB, publicId);
  if (!refreshedUser) {
    return c.json({ error: "Failed to reload central identity user." }, 500);
  }

  await ensureAppUserRow(c.env.DB, {
    id: String(refreshedUser.public_id || ""),
    email: String(refreshedUser.email || ""),
    auth_provider: "local",
    country_code: null,
    locale: null,
    handle: String(refreshedUser.handle || ""),
  });
  await updateAppUserHandle(
    c.env.DB,
    String(refreshedUser.public_id || ""),
    String(refreshedUser.handle || "")
  );

  return c.json({
    success: true,
    user: {
      server_id: String(refreshedUser.id || ""),
      public_id: String(refreshedUser.public_id || ""),
      email: String(refreshedUser.email || ""),
      handle: normalizeUserHandleInput(refreshedUser.handle),
      is_active: normalizeDbBoolean(refreshedUser.is_active, true),
      auth_version: Number(refreshedUser.auth_version || 0),
      created_at: String(refreshedUser.created_at || ""),
      updated_at: String(refreshedUser.updated_at || ""),
    },
  });
});

app.post("/api/find-share-users/resolve", async (c) => {
  await ensureCentralIdentitySchema(c.env.DB);

  const verified = await requireVerifiedCentralGrantUser(c);
  if ("error" in verified) return verified.error;

  const body = await c.req
    .json<{
      query?: string;
    }>()
    .catch(() => null);
  if (!body) {
    return c.json({ error: "Invalid request body" }, 400);
  }

  const resolved = await resolveCentralFindShareUserByQuery(c.env.DB, body.query);
  if (!resolved) {
    return c.json({ error: "No user matched the provided handle or email." }, 404);
  }
  if (resolved.public_id === verified.claims.public_id) {
    return c.json({ error: "You cannot invite the same account." }, 409);
  }

  return c.json({
    user: {
      public_id: resolved.public_id,
      email: resolved.email,
      handle: resolved.handle,
      display_label: resolved.display_label,
    },
  });
});

app.post("/api/find-shares", async (c) => {
  await ensureCentralIdentitySchema(c.env.DB);

  const verified = await requireVerifiedCentralGrantUser(c);
  if ("error" in verified) return verified.error;

  const body = await c.req
    .json<{
      invitee_public_id?: string;
      query?: string;
      owner_local_camera_id?: number;
      camera_name?: string;
      city?: string;
      state_code?: string;
      country_code?: string;
    }>()
    .catch(() => null);
  if (!body) {
    return c.json({ error: "Invalid request body" }, 400);
  }

  const inviteePublicId = normalizeText(body.invitee_public_id);
  const resolvedInvitee = inviteePublicId
    ? {
        public_id: inviteePublicId,
      }
    : await resolveCentralFindShareUserByQuery(c.env.DB, body.query);
  if (!resolvedInvitee?.public_id) {
    return c.json({ error: "No user matched the provided handle or email." }, 404);
  }

  try {
    const share = await createOrUpdateCentralCameraFindShare(c.env.DB, {
      ownerPublicId: verified.claims.public_id,
      inviteePublicId: resolvedInvitee.public_id,
      ownerLocalCameraId: clampInteger(body.owner_local_camera_id),
      cameraName: normalizeText(body.camera_name),
      city: normalizeOptionalText(body.city),
      stateCode: normalizeOptionalText(body.state_code),
      countryCode: normalizeCountryCode(body.country_code, null) || "BR",
    });
    if (!share) {
      return c.json({ error: "Failed to create the shared camera invitation." }, 500);
    }
    return c.json({ share }, 201);
  } catch (error) {
    const message =
      error instanceof Error && error.message
        ? error.message
        : "Failed to create the shared camera invitation.";
    return c.json({ error: message }, 400);
  }
});

