// Local auth endpoints
app.post("/api/auth/local/signup", async (c) => {
  // Ensure schema is initialized
  await ensureSchema(c.env.DB);
  
  try {
    const body = await c.req.json<{ 
      email: string; 
      password: string; 
      country_code?: string;
      locale?: string;
    }>();

    const email = normalizeEmail(body.email);
    const password = body.password;
    const countryCode =
      normalizeCountryCode(body.country_code, null) ||
      normalizeCountryCode(c.req.header("CF-IPCountry"), null) ||
      null;
    const locale = normalizeOptionalLocale(body.locale);

    // Validate email
    if (!isValidEmail(email)) {
      return c.json({ error: "Invalid email format" }, 400);
    }

    // Validate password
    if (!isValidPassword(password)) {
      return c.json({ error: "Password must be at least 8 characters" }, 400);
    }

    // Check if user already exists
    const existingUser = await findLocalUserIdentityCache(c.env.DB, { email });

    if (existingUser) {
      return c.json({ error: "Email already registered" }, 400);
    }

    if (isCentralIdentityClientConfigured(c.env)) {
      let centralResult: Awaited<ReturnType<typeof callCentralIdentityEndpoint>>;
      try {
        centralResult = await callCentralIdentityEndpoint(c.env, "/api/identity/signup", {
          email,
          password,
          country_code: countryCode,
        });
      } catch (error) {
        console.error("[AUTH] Central signup request failed:", error);
        return c.json({ error: "Unable to reach the central identity server." }, 502);
      }

      if (!centralResult.response.ok || !centralResult.verifiedGrant) {
        return c.json(
          {
            error: normalizeResponseErrorMessage(
              centralResult.data,
              "Central identity signup failed."
            ),
          },
          (centralResult.response.status || 502) as any
        );
      }

      const passwordHash = await bcrypt.hash(password, 10);
      const synced = await syncLocalIdentityCacheFromGrant(c.env.DB, {
        email,
        passwordHash,
        countryCode:
          normalizeCountryCode(centralResult.data?.user?.country_code, null) || countryCode,
        locale,
        serverHandle: normalizeUserHandleInput(centralResult.data?.user?.handle),
        verifiedGrant: centralResult.verifiedGrant,
      });

      if (!centralResult.verifiedGrant.claims.login_allowed) {
        return c.json(
          {
            error:
              centralResult.verifiedGrant.claims.reason || "This account is not allowed to log in.",
          },
          403
        );
      }

      await createLocalAuthSession(c, synced.localUserId);

      return c.json(
        {
          success: true,
          user: {
            id: synced.canonicalUserId,
            email,
            country_code: countryCode,
            handle:
              normalizeUserHandleInput(centralResult.data?.user?.handle) ||
              deriveHandleFromEmail(email),
          },
        },
        201
      );
    }

    // Hash password
    const passwordHash = await bcrypt.hash(password, 10);

    // Create user
    const now = new Date().toISOString();
    const result = await c.env.DB.prepare(
      `INSERT INTO local_users (email, password_hash, country_code, locale, last_login_at, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    )
      .bind(email, passwordHash, countryCode, locale, now, now, now)
      .run();

    const localUserId = result.meta.last_row_id;
    await c.env.DB
      .prepare(
        `UPDATE local_users
         SET pairing_client_id = ?,
             updated_at = ?
         WHERE id = ?`
      )
      .bind(`local:${localUserId}`, now, localUserId)
      .run();

    const localUser = await c.env.DB
      .prepare(`SELECT * FROM local_users WHERE id = ? LIMIT 1`)
      .bind(localUserId)
      .first();
    if (!localUser) {
      throw new Error("Failed to reload the new local user.");
    }

    const appUserId = resolveCanonicalAppUserIdFromLocalUserRow(localUser as any);

    // Create app user row
    await ensureAppUserRow(c.env.DB, {
      id: appUserId,
      email,
      auth_provider: "local",
      country_code: countryCode,
      locale,
    });

    // Create session
    await createLocalAuthSession(c, Number(localUserId || 0));

    return c.json({ 
      success: true,
      user: {
        id: appUserId,
        email,
        country_code: countryCode,
      }
    }, 201);
  } catch (error) {
    console.error("Signup error:", error);
    return c.json({ error: "Signup failed" }, 500);
  }
});

app.post("/api/auth/local/login", async (c) => {
  // Ensure schema is initialized
  await ensureSchema(c.env.DB);
  
  try {
    const body = await c.req.json<{ email: string; password: string }>();

    const email = normalizeEmail(body.email);
    const password = body.password;

    // Validate inputs
    if (!isValidEmail(email) || !password) {
      return c.json({ error: "Invalid email or password" }, 400);
    }

    // Find user
    const user = await findLocalUserIdentityCache(c.env.DB, { email });
    const userData = (user as any) || null;
    const hasLocalPassword = Boolean(userData?.password_hash);
    const passwordMatches =
      userData && hasLocalPassword
        ? await bcrypt.compare(password, String(userData.password_hash || ""))
        : false;
    const centralConfigured = isCentralIdentityClientConfigured(c.env);
    const requiresCentralGrant = localUserRequiresCentralGrant(userData);

    if (userData && passwordMatches && requiresCentralGrant) {
      if (!localUserGrantAllowsOfflineLogin(userData)) {
        if (!centralConfigured) {
          return c.json({ error: "Account requires online verification." }, 401);
        }
      } else {
        const now = new Date().toISOString();
        await c.env.DB
          .prepare(
            `UPDATE local_users
             SET last_login_at = ?,
                 updated_at = ?
             WHERE id = ?`
          )
          .bind(now, now, userData.id)
          .run();

        const appUserId = resolveCanonicalAppUserIdFromLocalUserRow(userData);
        await ensureAppUserRow(c.env.DB, {
          id: appUserId,
          email: userData.email,
          auth_provider: "local",
          country_code: userData.country_code || null,
          locale: userData.locale || null,
        });

        await createLocalAuthSession(c, Number(userData.id || 0));

        return c.json({
          success: true,
          user: {
            id: appUserId,
            email: userData.email,
            country_code: userData.country_code,
          },
        });
      }
    }

    const canAttemptCentralMigration =
      centralConfigured && Boolean(userData && passwordMatches && !requiresCentralGrant);
    const canAttemptCentralLogin =
      centralConfigured && (!userData || requiresCentralGrant || !passwordMatches);

    let preferredMigrationHandle: string | null = null;
    if (canAttemptCentralMigration && userData) {
      const profile = await getAppUserProfile(
        c.env.DB,
        resolveCanonicalAppUserIdFromLocalUserRow(userData)
      );
      preferredMigrationHandle = profile.handle;
    }

    if (canAttemptCentralMigration || canAttemptCentralLogin) {
      const targetPath = canAttemptCentralMigration
        ? "/api/identity/migrate-login"
        : "/api/identity/login";

      let centralResult: Awaited<ReturnType<typeof callCentralIdentityEndpoint>> | null = null;
      try {
        centralResult = await callCentralIdentityEndpoint(c.env, targetPath, {
          email,
          password,
          country_code: userData?.country_code || null,
          ...(canAttemptCentralMigration && preferredMigrationHandle
            ? { handle: preferredMigrationHandle }
            : {}),
        });
      } catch (error) {
        console.error("[AUTH] Central login request failed:", error);
        if (!canAttemptCentralMigration) {
          return c.json({ error: "Unable to reach the central identity server." }, 502);
        }
      }

      if (centralResult) {
        if (!centralResult.response.ok || !centralResult.verifiedGrant) {
          const status = centralResult.response.status || 502;
          const errorMessage = normalizeResponseErrorMessage(
            centralResult.data,
            "Central identity login failed."
          );

          if (canAttemptCentralMigration && status >= 500) {
            // Preserve legacy local login if the server is temporarily unavailable.
          } else {
            return c.json({ error: errorMessage }, status as any);
          }
        } else {
          const passwordHash = await bcrypt.hash(password, 10);
          const synced = await syncLocalIdentityCacheFromGrant(c.env.DB, {
            email,
            passwordHash,
            countryCode:
              normalizeCountryCode(centralResult.data?.user?.country_code, null) ||
              userData?.country_code ||
              null,
            locale: userData?.locale || null,
            serverHandle: normalizeUserHandleInput(centralResult.data?.user?.handle),
            verifiedGrant: centralResult.verifiedGrant,
          });

          if (!centralResult.verifiedGrant.claims.login_allowed) {
            return c.json(
              {
                error:
                  centralResult.verifiedGrant.claims.reason ||
                  "This account is not allowed to log in.",
              },
              403
            );
          }

          await createLocalAuthSession(c, synced.localUserId);

          return c.json({
            success: true,
            user: {
              id: synced.canonicalUserId,
              email,
              country_code: (synced.localUser as any)?.country_code || userData?.country_code || null,
              handle:
                normalizeUserHandleInput(centralResult.data?.user?.handle) ||
                deriveHandleFromEmail(email),
            },
          });
        }
      }
    }

    if (!userData || !passwordMatches) {
      return c.json({ error: "Invalid email or password" }, 401);
    }

    const now = new Date().toISOString();
    await c.env.DB
      .prepare(
        `UPDATE local_users
         SET last_login_at = ?,
             updated_at = ?,
             pairing_client_id = COALESCE(NULLIF(TRIM(pairing_client_id), ''), 'local:' || CAST(id AS TEXT))
         WHERE id = ?`
      )
      .bind(now, now, userData.id)
      .run();

    const refreshedLocalUser = await c.env.DB
      .prepare(`SELECT * FROM local_users WHERE id = ? LIMIT 1`)
      .bind(userData.id)
      .first();
    if (!refreshedLocalUser) {
      throw new Error("Failed to reload the local user after login.");
    }

    const appUserId = resolveCanonicalAppUserIdFromLocalUserRow(refreshedLocalUser as any);

    await ensureAppUserRow(c.env.DB, {
      id: appUserId,
      email: (refreshedLocalUser as any).email,
      auth_provider: "local",
      country_code: (refreshedLocalUser as any).country_code || null,
      locale: (refreshedLocalUser as any).locale || null,
    });

    await createLocalAuthSession(c, Number((refreshedLocalUser as any).id || 0));

    return c.json({
      success: true,
      user: {
        id: appUserId,
        email: (refreshedLocalUser as any).email,
        country_code: (refreshedLocalUser as any).country_code,
      },
    });
  } catch (error) {
    console.error("Login error:", error);
    return c.json({ error: "Login failed" }, 500);
  }
});

app.post("/api/auth/local/logout", async (c) => {
  const sessionToken = getCookie(c, LOCAL_SESSION_COOKIE_NAME);

  if (sessionToken) {
    // Delete session from database
    await c.env.DB.prepare(
      "DELETE FROM local_sessions WHERE session_token = ?"
    )
      .bind(sessionToken)
      .run();
  }

  // Clear cookie with same attributes
  setCookie(c, LOCAL_SESSION_COOKIE_NAME, "", {
    httpOnly: true,
    path: "/",
    sameSite: "none",
    secure: true,
    maxAge: 0,
  });

  return c.json({ success: true });
});

app.get("/api/auth/me", async (c) => {
  // Ensure schema is initialized
  await ensureSchema(c.env.DB);
  
  const localCookie = getCookie(c, LOCAL_SESSION_COOKIE_NAME);
  const googleCookie = getCookie(c, GOOGLE_SESSION_COOKIE_NAME);
  
  console.log("[auth/me] Local cookie exists:", !!localCookie);
  console.log("[auth/me] Google cookie exists:", !!googleCookie);
  
  // Check Google cookie FIRST (priority)
  if (googleCookie) {
    try {
      const user = await getGoogleSessionUser(c.env.DB, googleCookie);

      if (user) {
        void maybeEnsureSharedFindRelayForUser(c.env, {
          id: user.id,
          email: user.email,
        }).catch(() => {});
        console.log("[auth/me] -> google (canonical ID:", user.id, ")");
        return c.json({
          isAuthenticated: true,
          authProvider: "google",
          user: {
            id: user.id,
            email: user.email,
            country_code: user.country_code || null,
            google_user_data: user.google_user_data,
            created_at: user.created_at,
            handle: user.handle,
          },
        });
      }
    } catch (error) {
      console.error("[auth/me] Failed to get Google OAuth user:", error);
      if (shouldClearGoogleSessionOnAuthFailure(error)) {
        clearGoogleSessionCookie(c);
      }
    }
  }

  // Check local session only if Google not valid
  if (localCookie) {
    const session = await getLocalSessionUserByToken(c.env.DB, localCookie);

    if (session) {
      const sessionData = session as any;
      const appUserId = resolveCanonicalAppUserIdFromLocalUserRow(sessionData);
      await ensureAppUserRow(c.env.DB, {
        id: appUserId,
        email: sessionData.email,
        auth_provider: "local",
        country_code: sessionData.country_code || null,
        locale: sessionData.locale || null,
      });
      const profile = await getAppUserProfile(c.env.DB, appUserId);
      void maybeEnsureSharedFindRelayForUser(c.env, {
        id: appUserId,
        email: sessionData.email,
      }).catch(() => {});
      console.log("[auth/me] -> local");
      return c.json({
        isAuthenticated: true,
        authProvider: "local",
        user: {
          id: appUserId,
          email: sessionData.email,
          country_code: sessionData.country_code,
          created_at: profile.created_at,
          handle: profile.handle,
        },
      });
    }
  }

  console.log("[auth/me] -> not authenticated");
  return c.json({
    isAuthenticated: false,
    authProvider: null,
    user: null,
  });
});

app.patch("/api/user-profile", anyAuthMiddleware, async (c) => {
  await ensureSchema(c.env.DB);

  const user = c.get("user")!;
  const body = await c.req
    .json<{
      handle?: string;
    }>()
    .catch(() => null);

  if (!body) {
    return c.json({ error: "Invalid request body" }, 400);
  }

  const normalizedHandle = normalizeUserHandleInput(body.handle);
  if (!normalizedHandle || !isValidUserHandle(normalizedHandle)) {
    return c.json({ error: "Handle cannot be empty or contain spaces" }, 400);
  }

  const localIdentity =
    user.auth_provider === "local"
      ? await findLocalUserIdentityCache(c.env.DB, {
          email: user.email,
          serverPublicId: user.id,
        })
      : null;
  const serverPublicId =
    typeof (localIdentity as any)?.server_public_id === "string"
      ? String((localIdentity as any).server_public_id).trim()
      : "";
  const statusSignature =
    typeof (localIdentity as any)?.status_signature === "string"
      ? String((localIdentity as any).status_signature).trim()
      : "";

  if (user.auth_provider === "local" && serverPublicId) {
    if (!isCentralIdentityClientConfigured(c.env)) {
      return c.json({ error: "Central identity server is not configured." }, 503);
    }
    if (!statusSignature) {
      return c.json({ error: "This account requires a central identity refresh." }, 409);
    }

    let remoteResult: Awaited<ReturnType<typeof callCentralIdentityAuthorizedEndpoint>>;
    try {
      remoteResult = await callCentralIdentityAuthorizedEndpoint(
        c.env,
        "/api/identity/handle",
        {
          method: "PATCH",
          token: statusSignature,
          body: {
            handle: normalizedHandle,
          },
        }
      );
    } catch (error) {
      console.error("[AUTH] Central handle update request failed:", error);
      return c.json({ error: "Unable to reach the central identity server." }, 502);
    }

    if (!remoteResult.response.ok) {
      return c.json(
        {
          error: normalizeResponseErrorMessage(
            remoteResult.data,
            "Failed to update handle on the central identity server."
          ),
        },
        (remoteResult.response.status || 502) as any
      );
    }
  }

  await ensureAppUserRow(c.env.DB, {
    id: user.id,
    email: user.email,
    auth_provider: user.auth_provider,
    country_code: user.country_code || null,
    handle: normalizedHandle,
  });

  await updateAppUserHandle(c.env.DB, user.id, normalizedHandle);

  return c.json({
    success: true,
    handle: normalizedHandle,
  });
});

