app.post("/api/hub/cache/sync", anyAuthMiddleware, async (c) => {
  const user = c.get("user")!;
  const itemType = normalizeHubItemType(c.req.query("type"));
  const syncState = await c.env.DB
    .prepare(`SELECT * FROM hub_sync_state WHERE sync_key = ? LIMIT 1`)
    .bind(HUB_SYNC_STATE_KEY)
    .first();

  let cursor = normalizeText((syncState as any)?.last_cursor) || null;
  let syncedCount = 0;

  try {
    for (let iteration = 0; iteration < 10; iteration += 1) {
      let payload: { items: Array<Record<string, unknown>>; next_cursor: string | null; has_more: boolean };

      if (isCentralIdentityClientConfigured(c.env) && !isCentralIdentityServerConfigured(c.env)) {
        const relayContext = await resolveCurrentUserCentralRelayContext(c.env, user);
        const syncUrl = new URL("/api/hub/sync", buildCentralIdentityEndpointUrl(c.env, "/"));
        if (cursor) syncUrl.searchParams.set("cursor", cursor);
        if (itemType) syncUrl.searchParams.set("type", itemType);
        syncUrl.searchParams.set("limit", String(HUB_SYNC_BATCH_LIMIT));
        const remote = await callCentralIdentityAuthorizedEndpoint(c.env, `${syncUrl.pathname}${syncUrl.search}`, {
          method: "GET",
          token: relayContext.grantToken,
        });
        if (!remote.response.ok) {
          const message = normalizeResponseErrorMessage(remote.data, "Failed to synchronize Hub cache.");
          return c.json({ error: message }, remote.response.status as any);
        }
        payload = {
          items: Array.isArray(remote.data?.items) ? remote.data.items : [],
          next_cursor:
            typeof remote.data?.next_cursor === "string" ? remote.data.next_cursor : null,
          has_more: Boolean(remote.data?.has_more),
        };
      } else {
        const localPayload = await listPublishedHubSyncRows(c.env.DB, {
          cursor,
          itemType,
          limit: HUB_SYNC_BATCH_LIMIT,
        });
        payload = {
          items: localPayload.items,
          next_cursor: localPayload.nextCursor,
          has_more: localPayload.hasMore,
        };
      }

      if (payload.items.length === 0) {
        break;
      }

      await upsertHubItemsCache(c.env.DB, payload.items);
      syncedCount += payload.items.length;
      cursor = payload.next_cursor || cursor;

      if (!payload.has_more || !payload.next_cursor) {
        break;
      }
    }

    const now = new Date().toISOString();
    await c.env.DB
      .prepare(
        `INSERT INTO hub_sync_state (sync_key, last_cursor, last_sync_at, last_success_at, last_error)
         VALUES (?, ?, ?, ?, NULL)
         ON CONFLICT(sync_key) DO UPDATE SET
           last_cursor = excluded.last_cursor,
           last_sync_at = excluded.last_sync_at,
           last_success_at = excluded.last_success_at,
           last_error = NULL`
      )
      .bind(HUB_SYNC_STATE_KEY, cursor, now, now)
      .run();

    return c.json({ success: true, synced_count: syncedCount, cursor });
  } catch (error: any) {
    const now = new Date().toISOString();
    await c.env.DB
      .prepare(
        `INSERT INTO hub_sync_state (sync_key, last_cursor, last_sync_at, last_success_at, last_error)
         VALUES (?, ?, ?, NULL, ?)
         ON CONFLICT(sync_key) DO UPDATE SET
           last_cursor = excluded.last_cursor,
           last_sync_at = excluded.last_sync_at,
           last_error = excluded.last_error`
      )
      .bind(HUB_SYNC_STATE_KEY, cursor, now, normalizeText(error?.message || error))
      .run();
    console.error("[HUB] Failed to sync cache", error);
    return c.json({ error: "Failed to synchronize Hub cache" }, 500);
  }
});

