app.post("/api/hub/items/:itemId/install-agent-to-camera/:cameraId", anyAuthMiddleware, async (c) => {
  const user = c.get("user")!;
  const itemId = Number(c.req.param("itemId"));
  const cameraId = Number(c.req.param("cameraId"));
  if (!Number.isInteger(itemId) || itemId <= 0 || !Number.isInteger(cameraId) || cameraId <= 0) {
    return c.json({ error: "Invalid installation target" }, 400);
  }

  const item = await resolveHubInstallItem(c.env.DB, itemId);
  if (!item) {
    return c.json({ error: "Hub item not found. Synchronize the Hub cache first." }, 404);
  }
  if (item.item_type !== "agent") {
    return c.json({ error: "This Hub item is not an agent." }, 400);
  }

  const snapshot = normalizeHubAgentSnapshot(item.snapshot_json);
  if (!snapshot) {
    return c.json({ error: "Hub agent snapshot is invalid." }, 400);
  }

  try {
    const algorithmId = await createCameraAlgorithmFromHubSnapshot(
      c.env.DB,
      user.id,
      cameraId,
      snapshot,
      item.id,
      item.version_id
    );
    const agents = await listCustomCameraAgents(c.env.DB, user.id, cameraId);
    const agent = agents.find((row: any) => Number(row?.id) === algorithmId) || null;
    await recordHubDownloadInstall(c.env.DB, {
      itemId: item.id,
      versionId: item.version_id,
      userId: user.id,
      installTarget: "camera",
      targetRefJson: JSON.stringify({ camera_id: cameraId }),
      createdEntityType: "camera_algorithm",
      createdEntityId: algorithmId,
    });
    return c.json({ agent }, 201);
  } catch (error: any) {
    console.error("[HUB] Failed to install agent into camera", error);
    return c.json({ error: normalizeText(error?.message) || "Failed to install Hub agent" }, 500);
  }
});

app.post("/api/hub/items/:itemId/install-agent-to-step-target", anyAuthMiddleware, async (c) => {
  const user = c.get("user")!;
  const itemId = Number(c.req.param("itemId"));
  if (!Number.isInteger(itemId) || itemId <= 0) {
    return c.json({ error: "Invalid Hub item id" }, 400);
  }

  const body = await c.req
    .json<{
      step_id?: number;
      camera_id?: number | null;
    }>()
    .catch(() => null);
  if (!body) {
    return c.json({ error: "Invalid request body" }, 400);
  }
  const stepId = Number(body.step_id);
  const cameraId =
    body.camera_id === null || body.camera_id === undefined ? null : Number(body.camera_id);
  if (!Number.isInteger(stepId) || stepId <= 0) {
    return c.json({ error: "Invalid step_id" }, 400);
  }
  if (cameraId !== null && (!Number.isInteger(cameraId) || cameraId === 0)) {
    return c.json({ error: "Invalid camera_id" }, 400);
  }

  const item = await resolveHubInstallItem(c.env.DB, itemId);
  if (!item) {
    return c.json({ error: "Hub item not found. Synchronize the Hub cache first." }, 404);
  }
  if (item.item_type !== "agent") {
    return c.json({ error: "This Hub item is not an agent." }, 400);
  }

  const snapshot = normalizeHubAgentSnapshot(item.snapshot_json);
  if (!snapshot) {
    return c.json({ error: "Hub agent snapshot is invalid." }, 400);
  }

  try {
    const agentId = await upsertStepAgentFromHubSnapshot(
      c.env.DB,
      user.id,
      stepId,
      cameraId,
      snapshot,
      item.id,
      item.version_id
    );
    const { results } = await c.env.DB
      .prepare(`SELECT * FROM job_step_agents WHERE step_id = ? ORDER BY created_at DESC`)
      .bind(stepId)
      .all();
    const agent = (results || []).find((row: any) => Number(row?.id) === agentId) || null;
    await recordHubDownloadInstall(c.env.DB, {
      itemId: item.id,
      versionId: item.version_id,
      userId: user.id,
      installTarget: "step_camera",
      targetRefJson: JSON.stringify({ step_id: stepId, camera_id: cameraId }),
      createdEntityType: "job_step_agent",
      createdEntityId: agentId,
    });
    return c.json({ agent }, 201);
  } catch (error: any) {
    console.error("[HUB] Failed to install agent into step", error);
    return c.json({ error: normalizeText(error?.message) || "Failed to install Hub agent" }, 500);
  }
});

